<script setup>
import {ref,watch,onMounted,onBeforeUnmount,computed} from 'vue';
import * as THREE from 'three';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
import {receiverPreviewFrame,createReceiverPreviewGroup,disposeReceiverPreviewGroup,fitReceiverPreviewCamera} from './receiver-preview-scene.js';
import {nativeTriangleForHit,validateNativePreviewScene,highlightNativeElement} from './native-preview-scene.js';
import {traceNativeTriangle} from '../shared/native-resource-budget.mjs';
const props=defineProps({sceneData:{type:Object,required:true},manifest:{type:Object,required:true},triangle:{type:Number,required:true}}),emit=defineEmits(['close','select']);
const viewport=ref(null),closeButton=ref(null),error=ref(''),ready=ref(false),ceilings=ref(false),wireframe=ref(false);
const selected=computed(()=>{try{return traceNativeTriangle(props.manifest,props.triangle);}catch{return null;}});
let renderer,camera,scene,controls,group,observer,frame,disposed=false,previousFocus,pointerStart;
function highlight(){if(group)highlightNativeElement(group,selected.value?.elementId);}
function rebuild(){if(!scene)return;if(group){scene.remove(group);disposeReceiverPreviewGroup(group);}group=createReceiverPreviewGroup(props.sceneData,{ceilings:ceilings.value||selected.value?.kind==='ceiling',wireframe:wireframe.value});scene.add(group);highlight();}
function fit(){if(!camera)return;const r=viewport.value.getBoundingClientRect();fitReceiverPreviewCamera(camera,receiverPreviewFrame(props.sceneData).span,Math.max(1,r.width)/Math.max(1,r.height));controls.target.set(0,0,0);controls.update();}
function choose(event){const entry=props.manifest.elements.find(e=>e.elementId===event.target.value);if(entry)emit('select',entry.firstTriangle);}
function pick(event){if(!pointerStart||Math.hypot(event.clientX-pointerStart.x,event.clientY-pointerStart.y)>5){pointerStart=null;return;}pointerStart=null;if(!group||!camera)return;const r=renderer.domElement.getBoundingClientRect(),ray=new THREE.Raycaster();camera.updateMatrixWorld(true);group.updateMatrixWorld(true);ray.setFromCamera(new THREE.Vector2((event.clientX-r.left)/r.width*2-1,-(event.clientY-r.top)/r.height*2+1),camera);const hit=ray.intersectObjects(group.children,false)[0];if(hit)emit('select',nativeTriangleForHit(props.manifest,hit.object.userData.id,hit.faceIndex));}
function down(event){pointerStart=event.button===0?{x:event.clientX,y:event.clientY}:null;}
watch([ceilings,wireframe],rebuild);watch(()=>props.triangle,()=>{if(group?.children.some(m=>m.userData.kind==='ceiling')!==(ceilings.value||selected.value?.kind==='ceiling'))rebuild();else highlight();});
onMounted(()=>{previousFocus=document.activeElement;closeButton.value?.focus();try{
 validateNativePreviewScene(props.sceneData,props.manifest);renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.domElement.setAttribute('aria-label','Native source geometry canvas');viewport.value.appendChild(renderer.domElement);renderer.domElement.addEventListener('pointerdown',down);renderer.domElement.addEventListener('pointerup',pick);
 scene=new THREE.Scene();scene.background=new THREE.Color(0xe6ece4);scene.add(new THREE.HemisphereLight(0xffffff,0x596b60,2));const sun=new THREE.DirectionalLight(0xffffff,2);sun.position.set(4,8,5);scene.add(sun);camera=new THREE.PerspectiveCamera(45,1,.01,1000);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;rebuild();fit();observer=new ResizeObserver(()=>{if(disposed)return;const r=viewport.value.getBoundingClientRect();renderer.setSize(Math.max(1,r.width),Math.max(1,r.height));camera.aspect=Math.max(1,r.width)/Math.max(1,r.height);camera.updateProjectionMatrix();});observer.observe(viewport.value);const animate=()=>{if(disposed)return;controls.update();renderer.render(scene,camera);frame=requestAnimationFrame(animate);};animate();ready.value=true;
 }catch(cause){error.value='Native source preview unavailable: '+cause.message;}});
onBeforeUnmount(()=>{disposed=true;cancelAnimationFrame(frame);observer?.disconnect();controls?.dispose();renderer?.domElement.removeEventListener('pointerdown',down);renderer?.domElement.removeEventListener('pointerup',pick);disposeReceiverPreviewGroup(group);renderer?.dispose();renderer?.forceContextLoss();renderer?.domElement.remove();if(previousFocus?.isConnected)previousFocus.focus({preventScroll:true});});
</script>
<template><section class="native-source-preview" role="dialog" aria-label="Native source geometry preview" aria-modal="false" @keydown.stop @keydown.esc.prevent="emit('close')"><header><h3>Native source geometry preview</h3><button ref="closeButton" @click="emit('close')">Close native source preview</button></header><p>Verified bundle geometry · browser preview · click to select, drag to orbit, wheel to zoom. Selection highlights the complete source element. Selecting a ceiling reveals it while selected. Native engine picking and live physics remain disconnected.</p><div><label>Native preview source element<select aria-label="Native preview source element" :value="selected?.elementId??''" @change="choose"><option v-if="!selected" value="" disabled>Choose an element</option><option v-for="entry in manifest.elements" :key="entry.elementId" :value="entry.elementId">{{ entry.roomId }} · {{ entry.kind }} · {{ entry.wallId??entry.furnitureId??'' }}</option></select></label><button :disabled="!ready" @click="fit">Fit native source geometry</button><label><input v-model="ceilings" type="checkbox">Show native preview ceilings</label><label><input v-model="wireframe" type="checkbox">Native preview wireframe</label></div><p v-if="ready" data-testid="native-preview-ready">Preview ready: {{ manifest.summary.triangles }} triangles</p><p v-if="error" role="alert">{{ error }}</p><p data-testid="native-preview-selection" role="status">{{ selected?JSON.stringify(selected):'Choose a valid triangle or source element.' }}</p><div ref="viewport" class="native-source-canvas"></div></section></template>
<style>
.native-source-preview{position:fixed;inset:4vh 4vw;z-index:210;display:flex;flex-direction:column;padding:16px;gap:8px;background:#edf1e8;color:#263e3c;box-shadow:0 8px 50px #0007;overflow:auto}.native-source-preview header{display:flex;justify-content:space-between;gap:12px;align-items:center}.native-source-preview h3,.native-source-preview p{margin:2px 0}.native-source-preview p{font-size:12px;overflow-wrap:anywhere}.native-source-preview label{display:inline-flex;align-items:center;gap:4px;margin-right:8px;font-size:12px}.native-source-canvas{flex:1;min-height:220px;overflow:hidden}.native-source-canvas canvas{display:block;width:100%;height:100%;touch-action:none}
</style>
